import { createApp } from "vue";
import ChecksPanel from "./ChecksPanel.vue";
import "./styles.css";

const ROOT_TEST_ID = "orso-checks-panel-host";

function mount() {
  document.querySelectorAll(`[data-testid="${ROOT_TEST_ID}"]`).forEach((el) => el.remove());

  const host = document.createElement("div");
  host.dataset.testid = ROOT_TEST_ID;
  host.setAttribute("data-orso-checks", "host");
  Object.assign(host.style, {
    position: "fixed",
    right: "12px",
    bottom: "12px",
    zIndex: "2147483646",
  });

  const shadow = host.attachShadow({ mode: "open" });
  const mountEl = document.createElement("div");
  shadow.append(mountEl);
  document.documentElement.append(host);

  // Move injected Vite CSS into the shadow root so utilities apply to the panel.
  const app = createApp(ChecksPanel);
  app.mount(mountEl);

  requestAnimationFrame(() => {
    for (const style of Array.from(document.querySelectorAll("style[data-vite-dev-id], style"))) {
      const text = style.textContent ?? "";
      if (!text.includes("orso-checks-root") && !text.includes("--color-primary")) continue;
      const clone = style.cloneNode(true) as HTMLStyleElement;
      shadow.prepend(clone);
    }
    // css-injected-by-js appends a style to document head on import — pull the last few.
    for (const style of Array.from(document.head.querySelectorAll("style")).slice(-4)) {
      const text = style.textContent ?? "";
      if (text.includes(".bg-primary") || text.includes("orso-checks-root") || text.includes("--color-card")) {
        shadow.prepend(style.cloneNode(true));
      }
    }
  });
}

if (typeof document !== "undefined") {
  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", mount, { once: true });
  } else {
    mount();
  }
}

