export type BridgeMessage =
  | { type: typeof BRIDGE_TYPE; op: "pick"; element: PickedElement }
  | { type: typeof BRIDGE_TYPE; op: "cancel" }
  | { type: typeof BRIDGE_TYPE; op: "path"; url: string }
