import { describe, expect, it } from "vitest";
import { localizePreviewAssetUrl, previewMediaSrc } from "./previewAsset";

describe("localizePreviewAssetUrl", () => {
  const page = "http://127.0.0.1:51995/preview/astro-marketing/blog/";

  it("keeps assets already on the preview origin", () => {
    expect(
      localizePreviewAssetUrl(
        "http://127.0.0.1:51995/preview/astro-marketing/favicon.svg",
        page,
      ),
    ).toBe("http://127.0.0.1:51995/preview/astro-marketing/favicon.svg");
  });

  it("maps a published absolute URL onto the live preview origin by pathname", () => {
    expect(
      localizePreviewAssetUrl(
        "https://astro-marketing.blaisetiong-dev.workers.dev/preview/astro-marketing/og.png",
        page,
      ),
    ).toBe("http://127.0.0.1:51995/preview/astro-marketing/og.png");
  });

  it("resolves a site-root asset against the preview base path", () => {
    expect(localizePreviewAssetUrl("https://example.com/og.png", page)).toBe(
      "http://127.0.0.1:51995/preview/astro-marketing/og.png",
    );
  });

  it("resolves relative hrefs against the page URL", () => {
    expect(localizePreviewAssetUrl("/preview/astro-marketing/favicon.svg", page)).toBe(
      "http://127.0.0.1:51995/preview/astro-marketing/favicon.svg",
    );
  });

  it("returns empty for missing href", () => {
    expect(localizePreviewAssetUrl("", page)).toBe("");
  });
});

describe("previewMediaSrc", () => {
  const page = "http://127.0.0.1:51995/preview/site-1/";

  it("rewrites preview-path assets onto the UI origin with the auth token", () => {
    expect(
      previewMediaSrc(
        "https://cdn.example/preview/site-1/og.png",
        page,
        { uiOrigin: "http://localhost:5173", token: "abc" },
      ),
    ).toBe("http://localhost:5173/preview/site-1/og.png?t=abc");
  });

  it("keeps non-preview remote URLs when they cannot be localized under /preview", () => {
    // Still localized onto the preview base; then proxied.
    expect(
      previewMediaSrc("https://cdn.example/brand.png", page, {
        uiOrigin: "http://localhost:5173",
        token: "abc",
      }),
    ).toBe("http://localhost:5173/preview/site-1/brand.png?t=abc");
  });
});

/** Map a page asset URL onto the live preview origin so the CMS can load it. */

/** `/preview/{projectId}/` prefix from a framed preview pathname, or the directory of the path. */
export function previewBasePath(pathname: string): string {
  const match = pathname.match(/^(\/preview\/[^/]+\/)/);
  if (match) return match[1]!;
  if (pathname.endsWith("/")) return pathname;
  const slash = pathname.lastIndexOf("/");
  return slash >= 0 ? pathname.slice(0, slash + 1) : "/";
}

/**
 * Rewrite a favicon / OG / similar href so it points at the running preview server.
 * Published absolute URLs (CDN / SITE) often 404 locally; the same path under the
 * framed origin usually serves the file.
 */
export function localizePreviewAssetUrl(href: string, pageUrl: string): string {
  const value = href.trim();
  if (!value) return "";
  try {
    const page = new URL(pageUrl);
    const asset = new URL(value, pageUrl);
    if (asset.protocol !== "http:" && asset.protocol !== "https:") return value;
    if (asset.origin === page.origin) return asset.href;

    const base = previewBasePath(page.pathname);
    const path = asset.pathname;
    if (path.startsWith(base) || path.startsWith("/preview/")) {
      return new URL(path + asset.search + asset.hash, page.origin).href;
    }
    return new URL(path.replace(/^\//, "") + asset.search + asset.hash, page.origin + base).href;
  } catch {
    return value;
  }
}

export type PreviewMediaOpts = {
  /** Origin of the CMS UI (Vite or daemon shell), used for same-origin `/preview` loads. */
  uiOrigin: string;
  /** Daemon `?t=` / Bearer token so proxied preview assets authenticate. */
  token?: string;
};

/**
 * URL suitable for an `<img src>` in the CMS shell: localized onto the preview path,
 * then served from the UI origin (Vite → daemon proxy) with the auth token.
 */
export function previewMediaSrc(
  href: string,
  pageUrl: string,
  opts: PreviewMediaOpts,
): string {
  const localized = localizePreviewAssetUrl(href, pageUrl);
  if (!localized) return "";
  try {
    const asset = new URL(localized);
    if (!asset.pathname.startsWith("/preview/")) return localized;
    const proxied = new URL(asset.pathname + asset.search + asset.hash, opts.uiOrigin);
    if (opts.token) proxied.searchParams.set("t", opts.token);
    return proxied.href;
  } catch {
    return localized;
  }
}

